#!/usr/bin/env node
/**
 * Regenerate `src/features/languages/es/esReviewPool.ts` from the curriculum.
 *
 *   node scripts/gen-es-review-pool.mjs
 *
 * The pool is a cycle-safe snapshot of every `ES_M{N}_ATOMS` declaration. Its
 * header pointed at `scratchpad/gen-pool.mjs`, which no longer exists — so the
 * file was generated by a script nobody could run. This is that script, in the
 * repo, where the next module can use it.
 */
import { readFile, readdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const ES = resolve(here, "../src/features/languages/es");
const CURRICULUM = join(ES, "curriculum");

const files = (await readdir(CURRICULUM))
  .filter((f) => /^m\d+\.ts$/.test(f))
  .sort((a, b) => Number(a.slice(1, -3)) - Number(b.slice(1, -3)));

const rows = [];
const seen = new Set(); // first-write-wins by surface, mirroring courseAtoms.ts
for (const f of files) {
  const src = await readFile(join(CURRICULUM, f), "utf8");
  for (const [, body] of src.matchAll(/atom\(\{([^}]*)\}\)/g)) {
    const get = (k) => body.match(new RegExp(`${k}:\\s*"([^"]*)"`))?.[1];
    const surface = get("surface");
    if (!surface || seen.has(surface)) continue;
    seen.add(surface);
    rows.push({
      surface,
      gloss: get("meaningEn") ?? "",
      kind: get("kind") ?? "vocab",
      fromModule: get("fromModule") ?? f.slice(0, -3),
      partOfSpeech: get("partOfSpeech") ?? "other",
    });
  }
}

const q = (s) => JSON.stringify(s);
const header = (await readFile(join(ES, "esReviewPool.ts"), "utf8")).split(
  "export const ES_REVIEW_POOL",
)[0];
await writeFile(
  join(ES, "esReviewPool.ts"),
  header +
    "export const ES_REVIEW_POOL: EsReviewEntry[] = [\n" +
    rows
      .map(
        (r) =>
          `  { surface: ${q(r.surface)}, gloss: ${q(r.gloss)}, kind: ${q(r.kind)}, fromModule: ${q(r.fromModule)}, partOfSpeech: ${q(r.partOfSpeech)} },`,
      )
      .join("\n") +
    "\n];\n",
);
console.log(`${rows.length} atoms from ${files.length} modules → esReviewPool.ts`);
